// Every type comes from the running API's OpenAPI document (openapi.json, regenerated by
// `npm run gen:types`). A server change that the screens do not follow fails the typecheck.
import type { components } from "./schema";

type S = components["schemas"];

export type Approval = S["Approval"];
export type AskResponse = S["AskResponse"];
export type BoughtRow = S["BoughtRow"];
export type DcOrders = S["DcOrders"];
export type DcTotals = S["DcTotals"];
export type FarmerVolumeForecast = S["FarmerVolumeForecast"];
export type Health = S["HealthResponse"];
export type KillSwitchResponse = S["KillSwitchResponse"];
export type LoginResponse = S["LoginResponse"];
export type MarkdownPayload = S["MarkdownPayload"];
export type OrderPayload = S["OrderPayload"];
export type OutcomeInput = S["OutcomeInput"];
export type OutcomeRecord = S["OutcomeRecord"];
export type ProductOrders = S["ProductOrders"];
export type PriceQuote = S["PriceQuote"];
export type ProductTotal = S["ProductTotal"];
export type Range = S["Range"];
export type Scorecard = S["Scorecard"];
export type StoreContact = S["StoreContact"];
export type Suggestion = S["Suggestion"];
export type SurplusPayload = S["SurplusPayload"];
export type TransferPayload = S["TransferPayload"];
export type WeekHistory = S["WeekHistory"];
export type StoreWeek = S["StoreWeek"];
export type DayHistory = S["DayHistory"];
export type TrimmingHint = S["TrimmingHint"];

export type Role = Suggestion["approver_role"];
export type Driver = Suggestion["drivers"][number];
